parameters.jsCode:
const item = $input.all()[0];
const m = item.json.data || {};

const 日期 = m.date || '未知日期';
const appointments = m.appointment_count || 0;
const uniquePatients = m.appointment_unique_patient_count || 0;
const completed = m.appointment_completed_count || 0;
const cancelled = m.appointment_cancelled_count || 0;
const records = m.total_visit_count || 0;
const income = m.total_income || 0;
const expense = m.total_expense || 0;
const netProfit = m.net_profit || 0;
const cancelRate = appointments === 0 ? 0 : (cancelled * 100 / appointments).toFixed(1);
const visitPatients = m.visit_patient_count || 0;
const returningVisits = m.returning_visit_count || 0;
const arrears = m.arrears_amount || 0;

let text = '📊 营业简报 | ' + 日期 + '（' + (m.day_of_week || '') + '）\n';
text += '━━━━━━━━━━━━━━━━━━━━\n\n';
text += '👥 今日运营\n';
text += '   预约: ' + appointments + '人（接诊' + visitPatients + '人 | 复诊' + returningVisits + '人次 | 取消' + cancelled + '人）\n';
text += '   病历: ' + records + '份 | 完成治疗: ' + completed + '例\n';
text += '💰 当日收支\n';
text += '   收入: ¥' + income.toFixed(2) + ' | 支出: ¥' + expense.toFixed(2) + ' | 净利润: ¥' + netProfit.toFixed(2) + '\n';
text += '📉 取消率: ' + cancelRate + '%';
if (arrears > 0) {
  text += ' | 欠款: ¥' + arrears.toFixed(2);
}
text += '\n\n';

if (m.top_doctors && m.top_doctors.length > 0) {
  text += '👨‍⚕️ 医生排行\n';
  m.top_doctors.forEach(function(d, i) {
    text += '   ' + (i + 1) + '. ' + d.doctor_name + ' | 预约' + (d.appointment_count || 0) + '人 | 治疗' + (d.treatment_count || 0) + '例 | 收入¥' + ((d.treatment_revenue || 0)).toFixed(2) + '\n';
  });
  text += '\n';
}

if (m.top_projects && m.top_projects.length > 0) {
  text += '🏆 项目排行\n';
  m.top_projects.forEach(function(p, i) {
    text += '   ' + (i + 1) + '. ' + p.project_name + ' | ' + (p.case_count || 0) + '例 | ¥' + ((p.revenue || 0)).toFixed(2) + '\n';
  });
  text += '\n';
}

return [{ json: { brief: text, date: 日期 } }];

